/* ── Escada de revisão ────────────────────────────────────────────────
   Cada esquema é uma lista de dias contados a partir da data em que a aula
   foi estudada. O esquema em uso fica em data.revisao, e quem monta a
   escada é a função escada(), logo abaixo. LADDER continua existindo como
   o padrão da casa e como reserva quando a configuração vem quebrada. */

/* Só arredonda para semana, mês ou ano quando o número fecha certinho.
   Nove dias vira "9 dias", não "1 sem": arredondar aqui esconderia da
   pessoa o intervalo que ela mesma escreveu. */
function rotuloDias(d) {
  if (d >= 365 && d % 365 === 0) { const a = d / 365; return `${a} ano${a === 1 ? "" : "s"}`; }
  if (d >= 30 && d % 30 === 0) { const m = d / 30; return `${m} ${m === 1 ? "mês" : "meses"}`; }
  if (d >= 7 && d < 30 && d % 7 === 0) return `${d / 7} sem`;
  return `${d} dia${d === 1 ? "" : "s"}`;
}

