const ESQUEMA_PADRAO = ESQUEMAS[0];
const MAX_DEGRAUS = 8;

/* Limpa uma lista de dias vinda do que a pessoa digitou ou do arquivo salvo. */
function limparDias(lista) {
  const dias = [...new Set((Array.isArray(lista) ? lista : [])
    .map((x) => Math.round(Number(x)))
    .filter((x) => Number.isFinite(x) && x >= 1 && x <= 3650))]
    .sort((a, b) => a - b)
    .slice(0, MAX_DEGRAUS);
  return dias;
}

/* A escada em uso, já com rótulo em cada degrau. */
function escada(revisao) {
  const cfg = revisao || {};
  const modelo = ESQUEMAS.find((e) => e.id === cfg.esquema) || ESQUEMA_PADRAO;
  const dias = modelo.id === "personalizado"
    ? (limparDias(cfg.dias).length ? limparDias(cfg.dias) : modelo.dias)
    : modelo.dias;
  return dias.map((d) => ({ d, label: rotuloDias(d) }));
}

