/* O identificador de cada aula vem do próprio cronograma e é fixo, então
   reordenar a lista não desloca o progresso de ninguém. O "week" guarda o
   bloco de especialidade, que é como o cronograma é agrupado na tela. */
const CURRICULUM = CURSO.map((a) => ({
  id: a.id, week: a.bloco, area: a.area, title: a.titulo, esp: a.esp,
  bonus: Array.isArray(a.topicos) ? a.topicos : [],
}));

/* Tradução do formato antigo, em que o id era a posição na lista. */
const ID_NOVO = (velho) => {
  const m = /^m(\d+)$/.exec(String(velho || ""));
  if (!m) return null;
  return ID_ANTIGO[Number(m[1])] || null;
};

/* Especialidades de cada área, na ordem em que aparecem no cronograma.
   Sai da própria lista, então acrescentar aula não pede manutenção aqui. */
const ORDEM_ESP = CURSO.reduce((m, a) => {
  if (!m[a.area]) m[a.area] = [];
  if (m[a.area].indexOf(a.esp) < 0) m[a.area].push(a.esp);
  return m;
}, {});
const BY_ID = CURRICULUM.reduce((m, s) => { m[s.id] = s; return m; }, {});
const TOTAL_BONUS = CURRICULUM.reduce((a, s) => a + s.bonus.length, 0);

