const pad = (n) => String(n).padStart(2, "0");
const toISO = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
function fromISO(s) {
  if (!s || typeof s !== "string") return new Date();
  const p = s.split("-").map(Number);
  return new Date(p[0], (p[1] || 1) - 1, p[2] || 1);
}
const todayISO = () => toISO(new Date());
function addDays(iso, n) { const d = fromISO(iso); d.setDate(d.getDate() + n); return toISO(d); }
function diffDays(a, b) { return Math.round((fromISO(b) - fromISO(a)) / 86400000); }
function weekStart(iso) { const d = fromISO(iso); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return toISO(d); }
function brDate(iso) { if (!iso) return "—"; const p = String(iso).split("-"); return `${p[2]}/${p[1]}/${p[0].slice(2)}`; }
function fmtMin(min) {
  const m = Math.max(0, Math.round(min || 0)), h = Math.floor(m / 60), r = m % 60;
  if (h === 0) return `${r}min`;
  if (r === 0) return `${h}h`;
  return `${h}h${pad(r)}`;
}
const fmtClock = (s) => { const v = Math.max(0, Math.floor(s || 0)); return `${pad(Math.floor(v / 60))}:${pad(v % 60)}`; };
function fmtRelogio(s) {
  const v = Math.max(0, Math.floor(s || 0));
  const h = Math.floor(v / 3600), m = Math.floor((v % 3600) / 60), g = v % 60;
  return h > 0 ? `${h}:${pad(m)}:${pad(g)}` : `${pad(m)}:${pad(g)}`;
}
const uid = () => Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-4);
const toMin = (v) => { const p = String(v || "0:0").split(":").map(Number); return (p[0] || 0) * 60 + (p[1] || 0); };

function rotuloSemana(ini) {
  const a = fromISO(ini), b = fromISO(addDays(ini, 6));
  const m1 = MESES[a.getMonth()], m2 = MESES[b.getMonth()];
  if (m1 === m2) return `${a.getDate()} a ${b.getDate()} de ${m1}`;
  return `${a.getDate()} de ${m1} a ${b.getDate()} de ${m2}`;
}
